from collections import deque,defaultdict
R,C=len(grid),len(grid[0]); seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  col=grid[r][c]
  if col==4 or (r,c) in seen: continue
  q=[(r,c)];seen.add((r,c)); cells=[]
  while q:
   x,y=q.pop();cells.append((x,y))
   for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
    a,b=x+dx,y+dy
    if 0<=a<R and 0<=b<C and (a,b) not in seen and grid[a][b]==col:
     seen.add((a,b));q.append((a,b))
  minr=min(x for x,y in cells);minc=min(y for x,y in cells)
  shape=tuple(sorted((x-minr,y-minc) for x,y in cells))
  comps.append({'color':col,'cells':cells,'size':len(cells),'origin':(minr,minc),'shape':shape})
for i,co in enumerate(comps): print(i,co['color'],co['size'],co['origin'],co['shape'])
